/**
 * Liquor color: the measured color of the brewed tea in each session's cup photo.
 *
 * Data is generated by `pnpm liquor` (scripts/liquor-colors.mjs) into
 * src/generated/liquor-colors.json, keyed by session `_slug`. Sessions without a usable
 * cup photo fall back to a warm amber.
 *
 * Pure module (no React/jotai) so it is safe in server components.
 */
import liquorData from "@/generated/liquor-colors.json"

export type RGB = [number, number, number]

export type LiquorColor = {
	hex: string
	rgb: RGB
	/** OKLCH [L 0..1, C, H degrees], when measured */
	oklch?: [number, number, number]
	/** Image the color was sampled from, when measured */
	source?: string
	/** false when this is the amber fallback */
	measured: boolean
}

type LiquorEntry = {
	hex: string
	rgb: number[]
	oklch?: number[]
	source: string
	alt?: string
	confidence?: "alt" | "fallback"
}

const LIQUOR_MAP = liquorData as Record<string, LiquorEntry>

export const LIQUOR_FALLBACK: LiquorColor = {
	hex: "#d9a441",
	rgb: [217, 164, 65],
	measured: false,
}

export function getLiquorColor(slug: string | null | undefined): LiquorColor {
	const entry = slug ? LIQUOR_MAP[slug] : undefined
	if (!entry) return LIQUOR_FALLBACK
	return {
		hex: entry.hex,
		rgb: [entry.rgb[0], entry.rgb[1], entry.rgb[2]],
		oklch: entry.oklch ? [entry.oklch[0], entry.oklch[1], entry.oklch[2]] : undefined,
		source: entry.source,
		measured: true,
	}
}

/** Relative luminance (WCAG) of an sRGB triplet, 0..1 */
export function luminance([r, g, b]: RGB): number {
	const lin = (c: number) => {
		const s = c / 255
		return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
	}
	return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)
}

/** Readable ink (text) color to put on top of a liquor-colored fill. */
export function liquorInk(rgb: RGB): string {
	return luminance(rgb) > 0.28 ? "#121012" : "#ffffff"
}

// ---------------------------------------------------------------------------
// Text-safe accent
// ---------------------------------------------------------------------------

/** OKLCH → sRGB 0..255 (unclamped; check inGamut). */
function oklchToRgb(l: number, c: number, hDeg: number): [number, number, number] {
	const h = (hDeg * Math.PI) / 180
	const a = c * Math.cos(h)
	const b = c * Math.sin(h)
	const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3
	const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3
	const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3
	const lin = [
		4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
		-1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
		-0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_,
	]
	return lin.map((v) => {
		const s = v <= 0.0031308 ? 12.92 * v : 1.055 * Math.sign(v) * Math.abs(v) ** (1 / 2.4) - 0.055
		return s * 255
	}) as [number, number, number]
}

const inGamut = (rgb: number[]) => rgb.every((v) => v >= -0.5 && v <= 255.5)

const toHex = (rgb: RGB) => `#${rgb.map((v) => v.toString(16).padStart(2, "0")).join("")}`

/** Minimum OKLCH lightness for liquor used as text / thin marks on the #121012 ground (≥ ~7:1). */
export const LIQUOR_TEXT_MIN_L = 0.74
const LIQUOR_TEXT_MAX_C = 0.16

/**
 * The liquor as a readable accent on the dark ground: measured liquors darker than
 * LIQUOR_TEXT_MIN_L are lifted in OKLCH, keeping the hue (and as much chroma as sRGB allows), so
 * a dark shou reads as a warm russet rather than vanishing or washing out to grey. Pale liquors
 * pass through unchanged. Use for text, 1-2px strokes, dots; keep `--liquor` for fills.
 */
export function liquorTextRgb(color: LiquorColor, minL = LIQUOR_TEXT_MIN_L): RGB {
	if (!color.oklch) return liftLiquor(color.rgb)
	const [l, c, h] = color.oklch
	if (l >= minL) return color.rgb
	let chroma = Math.min(c, LIQUOR_TEXT_MAX_C)
	let rgb = oklchToRgb(minL, chroma, h)
	for (let i = 0; i < 24 && !inGamut(rgb); i++) {
		chroma *= 0.9
		rgb = oklchToRgb(minL, chroma, h)
	}
	return rgb.map((v) => Math.round(Math.min(255, Math.max(0, v)))) as unknown as RGB
}

export type LiquorCssVars = {
	"--liquor": string
	"--liquor-rgb": string
	"--liquor-ink": string
	/** text-safe accent (see liquorTextRgb) */
	"--liquor-text": string
	"--liquor-text-rgb": string
}

/** CSS custom props for a color: spread into a `style` prop. */
export function liquorVarsFromColor(color: LiquorColor): LiquorCssVars {
	const text = liquorTextRgb(color)
	return {
		"--liquor": color.hex,
		"--liquor-rgb": color.rgb.join(" "),
		"--liquor-ink": liquorInk(color.rgb),
		"--liquor-text": toHex(text),
		"--liquor-text-rgb": text.join(" "),
	}
}

/**
 * CSS custom props for a session: { "--liquor": "#b35710", "--liquor-rgb": "179 87 16", "--liquor-ink": "#fff" }.
 * Use as `style={liquorVars(slug) as React.CSSProperties}`; consume via
 * `var(--liquor)` or `rgb(var(--liquor-rgb) / 0.4)`.
 */
export function liquorVars(slug: string | null | undefined): LiquorCssVars {
	return liquorVarsFromColor(getLiquorColor(slug))
}

/**
 * The liquor color lifted toward white until it reads as an accent on the #121012 ground.
 * Pale liquors are measured dark and olive (see foundation notes); this keeps the hue.
 */
export function liftLiquor(rgb: RGB, minLuminance = 0.3): RGB {
	if (luminance(rgb) >= minLuminance) return rgb
	let lo = 0
	let hi = 1
	const mix = (t: number): RGB => rgb.map((c) => Math.round(c + (255 - c) * t)) as unknown as RGB
	for (let i = 0; i < 12; i++) {
		const mid = (lo + hi) / 2
		if (luminance(mix(mid)) < minLuminance) lo = mid
		else hi = mid
	}
	return mix(hi)
}

export const rgbCss = (rgb: RGB, alpha = 1) => `rgb(${rgb[0]} ${rgb[1]} ${rgb[2]} / ${alpha})`
